package com.queueless.controller;
import com.queueless.dao.QueueDAO; import com.queueless.model.QueueEntry; import com.queueless.util.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.util.*;
@WebServlet("/api/queue/list") public class QueueListServlet extends HttpServlet{
 protected void doGet(HttpServletRequest req,HttpServletResponse res)throws IOException{if(AuthUtil.require(req,res)==null)return;try{long sid=Long.parseLong(req.getParameter("serviceId"));QueueDAO d=new QueueDAO();List<QueueEntry>a=d.list(sid);res.setContentType("application/json;charset=UTF-8");StringBuilder b=new StringBuilder("{\"success\":true,\"entries\":[");for(int i=0;i<a.size();i++){QueueEntry q=a.get(i);if(i>0)b.append(',');b.append("{\"id\":").append(q.id).append(",\"token\":\"").append(q.token).append("\",\"name\":\"").append(JsonUtil.esc(q.name)).append("\",\"phone\":\"").append(JsonUtil.esc(q.phone)).append("\",\"registrationType\":\"").append(q.registrationType).append("\",\"status\":\"").append(q.status).append("\",\"registeredAt\":\"").append(JsonUtil.esc(q.registeredAt)).append("\"}");}b.append("]}");res.getWriter().write(b.toString());}catch(Exception e){res.setStatus(500);res.getWriter().write(JsonUtil.error("Unable to load queue."));}}
}
